{% set result = [] %}
{% for item in CTX.halo_actions.actions %}
    {% set obj = {'datetime': item.get('datetime'),
                  'outcome': item.get('outcome'),
                  'new_status_name': item.get('new_status_name'),
                  'note_html': item.get('note_html'),
                  'who': item.get('who')} %}
    {% set _ = result.append(obj) %}
{% endfor %}
{% set sorted_result = result | sort(attribute='datetime', reverse=True) %}

{% for item in sorted_result %}
    <br><h4>{{ item.datetime.split('T') | first }}</h4>
        <strong>Outcome:</strong> {{ item.outcome }}<br>
        <strong>New Status:</strong> {{ item.new_status_name }}<br>
        <strong>Who:</strong> {{ item.who }}<br>
        {% if item.note_html %}
    <strong>Note:</strong> {{ item.note_html.strip() }}
{% endif %}
{% endfor %}

